function globRegexBody(pattern) {
	const source = globRegexSource(pattern);
	return source.slice(1, source.length - 1);
}

function gitignoreRegexSource(pattern, anchoredP, directoryOnlyP) {
	const body = globRegexBody(pattern);
	if (anchoredP) {
		return `^${body}${directoryOnlyP ? "/" : "(?:$|/)" }`;
	}
	if (directoryOnlyP) {
		return `(?:^|/)${body}/`;
	}
	return `(?:^|/)${body}(?:$|/)`;
}

function runFindGlobRegex() {
	return {
		gr_star: globRegexSource("*") === "^[^/]*$" ? 1 : 0,
		gr_glob: globRegexSource("**") === "^.*$" ? 1 : 0,
		gr_q: globRegexSource("?") === "^[^/]$" ? 1 : 0,
		gr_dot: globRegexSource(".a") === "^\\.a$" ? 1 : 0,
	};
}

function runFindGlobSpecial() {
	return {
		gs_dot: GLOB_SPECIAL.has(".") ? 1 : 0,
		gs_star: GLOB_SPECIAL.has("*") ? 0 : 1,
		gs_pipe: GLOB_SPECIAL.has("|") ? 1 : 0,
		gs_bs: GLOB_SPECIAL.has("\\") ? 1 : 0,
	};
}

function runFindGitignoreRegex() {
	return {
		gi_plain: gitignoreRegexSource("foo", false, false) === "(?:^|/)foo(?:$|/)" ? 1 : 0,
		gi_anch: gitignoreRegexSource("foo", true, true) === "^foo/" ? 1 : 0,
		gi_dir: gitignoreRegexSource("foo", true, false) === "^foo(?:$|/)" ? 1 : 0,
	};
}

function leftoverGlobScanner(pattern, path) {
	return new RegExp(globRegexSource(pattern)).test(path);
}

function leftoverGlobRegexBody(pattern) {
	return globRegexBody(pattern);
}

function leftoverParseGitignoreLine(line, base = "/tmp") {
	let text = line;
	while (text.length > 0 && "\r \t".includes(text[text.length - 1])) {
		text = text.slice(0, -1);
	}
	if (text.length === 0 || text[0] === "#") return null;
	const escapedMarkerP =
		text.length > 1 && text[0] === "\\" && "#!".includes(text[1]);
	const negatedP = !escapedMarkerP && text[0] === "!";
	let raw;
	if (escapedMarkerP) raw = text.slice(1);
	else if (negatedP) raw = text.slice(1);
	else raw = text;
	const directoryOnlyP = raw.length > 0 && raw[raw.length - 1] === "/";
	const withoutTrailing = directoryOnlyP ? raw.slice(0, -1) : raw;
	const leadingSlashP = withoutTrailing.length > 0 && withoutTrailing[0] === "/";
	const pattern = leadingSlashP ? withoutTrailing.slice(1) : withoutTrailing;
	const anchoredP = leadingSlashP || pattern.includes("/");
	if (pattern.length === 0) return null;
	return {
		base,
		scanner: new RegExp(gitignoreRegexSource(pattern, anchoredP, directoryOnlyP)),
		negatedP,
	};
}

function runFindGlobScanner() {
	return {
		gsc_star: leftoverGlobScanner("*", "a.txt") ? 1 : 0,
		gsc_miss: leftoverGlobScanner("*", "foo/bar") ? 0 : 1,
		gsc_glob: leftoverGlobScanner("**", "foo/bar") ? 1 : 0,
		gsc_q: leftoverGlobScanner("?", "a") ? 1 : 0,
		gsc_dot: leftoverGlobScanner(".a", ".a") ? 1 : 0,
	};
}

function runFindGlobRegexBody() {
	return {
		grb_star: leftoverGlobRegexBody("*") === "[^/]*" ? 1 : 0,
		grb_glob: leftoverGlobRegexBody("**") === ".*" ? 1 : 0,
		grb_q: leftoverGlobRegexBody("?") === "[^/]" ? 1 : 0,
		grb_dot: leftoverGlobRegexBody(".a") === "\\.a" ? 1 : 0,
	};
}

function runFindParseGitignoreLine() {
	const empty = leftoverParseGitignoreLine("");
	const hash = leftoverParseGitignoreLine("# comment");
	const foo = leftoverParseGitignoreLine("foo");
	const bang = leftoverParseGitignoreLine("!foo");
	return {
		pgl_empty: empty === null ? 1 : 0,
		pgl_hash: hash === null ? 1 : 0,
		pgl_foo: foo ? 1 : 0,
		pgl_bang: bang && bang.negatedP ? 1 : 0,
		pgl_scan: foo && foo.scanner instanceof RegExp ? 1 : 0,
	};
}

const LEFTOVER_GITIGNORED_BASE = "/tmp/goal20-gitignored-base/";

function leftoverIgnoredDirectory(directory) {
	const ensured = directory.endsWith("/") ? directory : `${directory}/`;
	const parts = ensured.replaceAll("\\", "/").split("/").filter((part) => part.length > 0);
	const last = parts[parts.length - 1];
	return last === ".git" || last === "node_modules";
}

function leftoverIsSubpath(pathStr, base) {
	const nbase = base.endsWith("/") ? base : `${base}/`;
	return pathStr === base || pathStr === nbase.slice(0, -1) || pathStr.startsWith(nbase);
}

function leftoverRelativePosix(pathStr, cwd) {
	const base = cwd.endsWith("/") ? cwd : `${cwd}/`;
	if (pathStr.startsWith(base)) {
		return pathStr.slice(base.length).replaceAll("\\", "/");
	}
	if (pathStr === cwd || pathStr === base.slice(0, -1)) {
		return "";
	}
	return pathStr.replaceAll("\\", "/");
}

function leftoverGitignored(relative, rules) {
	const pathStr = `${LEFTOVER_GITIGNORED_BASE}${relative}`;
	let ignoredP = false;
	for (const rule of rules) {
		if (!leftoverIsSubpath(pathStr, rule.base)) continue;
		const rel = leftoverRelativePosix(pathStr, rule.base);
		if (rule.scanner.test(rel)) ignoredP = !rule.negatedP;
	}
	return ignoredP;
}

function leftoverMakeGlobTool(_cwd) {
	return {
		name: "glob",
		description:
			"Find files recursively with a glob pattern; follows .gitignore and ignores .git and node_modules.",
		parameters: { required: ["pattern"] },
		executionMode: "parallel",
	};
}

function runFindIgnoredDirectory() {
	return {
		igd_git: leftoverIgnoredDirectory("/tmp/.git") ? 1 : 0,
		igd_nm: leftoverIgnoredDirectory("/tmp/node_modules") ? 1 : 0,
		igd_src: leftoverIgnoredDirectory("/tmp/src") ? 0 : 1,
		igd_hub: leftoverIgnoredDirectory("/tmp/.github") ? 0 : 1,
		igd_slash: leftoverIgnoredDirectory("/tmp/proj/.git/") ? 1 : 0,
	};
}

function runFindGitignored() {
	const empty = [];
	const foo = [leftoverParseGitignoreLine("foo", LEFTOVER_GITIGNORED_BASE)].filter(Boolean);
	const bang = ["foo", "!foo"]
		.map((line) => leftoverParseGitignoreLine(line, LEFTOVER_GITIGNORED_BASE))
		.filter(Boolean);
	const outsidePath = "/var/tmp/goal20-gitignored-outside/foo";
	let outside = false;
	for (const rule of foo) {
		if (!leftoverIsSubpath(outsidePath, rule.base)) continue;
		const rel = leftoverRelativePosix(outsidePath, rule.base);
		if (rule.scanner.test(rel)) outside = !rule.negatedP;
	}
	return {
		gig_empty: leftoverGitignored("foo", empty) ? 0 : 1,
		gig_hit: leftoverGitignored("foo", foo) ? 1 : 0,
		gig_miss: leftoverGitignored("bar", foo) ? 0 : 1,
		gig_bang: leftoverGitignored("foo", bang) ? 0 : 1,
		gig_out: outside ? 0 : 1,
	};
}

