async function grepGetFileLines(filePath, cache) {
	let lines = cache.get(filePath);
	if (!lines) {
		try {
			const content = await fsReadFile(filePath, "utf-8");
			lines = content.replace(/\r\n/g, "\n").replace(/\r/g, "\n").split("\n");
		} catch {
			lines = [];
		}
		cache.set(filePath, lines);
	}
	return lines;
}


