const BASH_NOTICE_PATH = "/tmp/pi-bash-notice.log";
const BASH_NOTICE_FULL_OUTPUT = "keep\nLASTLINE";

function stripExitFooter(text, exitCode) {
	const footer = `Process exited with code ${exitCode}`;
	if (text === footer) return "";
	if (text.length > footer.length && text.endsWith(footer)) {
		const end = text.length - footer.length;
		if (end > 0 && text[end - 1] === "\n") return text.slice(0, end - 1);
		return text.slice(0, end);
	}
	return text;
}

function appendStatus(text, status) {
	return `${text ? `${text}\n\n` : ""}${status}`;
}

function bashTruncationNotice(details, outputPath, fullOutput) {
	if (!details.truncated) return "";
	const totalLines = details.totalLines;
	const outputLines = details.outputLines;
	const startLine = totalLines - outputLines + 1;
	const endLine = totalLines;
	if (details.lastLinePartial) {
		let lines = fullOutput.length === 0 ? [] : fullOutput.split("\n");
		if (lines.length && fullOutput.endsWith("\n")) lines = lines.slice(0, -1);
		const lastLine = lines.length ? lines[lines.length - 1] : "";
		return `[Showing last ${truncateModule.formatSize(details.outputBytes)} of line ${endLine} (line is ${truncateModule.formatSize(Buffer.byteLength(lastLine, "utf8"))}). Full output: ${outputPath}]`;
	}
	if (details.truncatedBy === "lines") {
		return `[Showing lines ${startLine}-${endLine} of ${totalLines}. Full output: ${outputPath}]`;
	}
	return `[Showing lines ${startLine}-${endLine} of ${totalLines} (${truncateModule.formatSize(truncateModule.DEFAULT_MAX_BYTES)} limit). Full output: ${outputPath}]`;
}

function runBashStripExitFooter() {
	const exact = stripExitFooter("Process exited with code 0", 0);
	const nl = stripExitFooter("hello\nProcess exited with code 1", 1);
	const noNl = stripExitFooter("helloProcess exited with code 2", 2);
	const plain = stripExitFooter("plain output", 3);
	const empty = stripExitFooter("", 4);
	return {
		sef_exact: exact === "" ? 1 : 0,
		sef_nl: nl === "hello" ? 1 : 0,
		sef_no_nl: noNl === "hello" ? 1 : 0,
		sef_plain: plain === "plain output" ? 1 : 0,
		sef_empty: empty === "" ? 1 : 0,
		sef_n: 5,
	};
}

function runBashAppendStatus() {
	const empty = appendStatus("", "Command aborted");
	const abort = appendStatus("out", "Command aborted");
	const exit = appendStatus("out", "Command exited with code 1");
	const timeout = appendStatus("out", "Command timed out after 5 seconds");
	return {
		abs_empty: empty === "Command aborted" ? 1 : 0,
		abs_abort: abort === "out\n\nCommand aborted" ? 1 : 0,
		abs_exit: exit === "out\n\nCommand exited with code 1" ? 1 : 0,
		abs_timeout: timeout === "out\n\nCommand timed out after 5 seconds" ? 1 : 0,
		abs_n: 4,
	};
}

function runBashTruncationNotice() {
	const none = bashTruncationNotice(
		{ truncated: false },
		BASH_NOTICE_PATH,
		BASH_NOTICE_FULL_OUTPUT,
	);
	const partial = bashTruncationNotice(
		{
			truncated: true,
			lastLinePartial: true,
			totalLines: 2,
			outputLines: 1,
			outputBytes: 8,
		},
		BASH_NOTICE_PATH,
		BASH_NOTICE_FULL_OUTPUT,
	);
	const lines = bashTruncationNotice(
		{
			truncated: true,
			truncatedBy: "lines",
			totalLines: 10,
			outputLines: 3,
		},
		BASH_NOTICE_PATH,
		BASH_NOTICE_FULL_OUTPUT,
	);
	const bytes = bashTruncationNotice(
		{
			truncated: true,
			truncatedBy: "bytes",
			totalLines: 10,
			outputLines: 3,
		},
		BASH_NOTICE_PATH,
		BASH_NOTICE_FULL_OUTPUT,
	);
	return {
		btn_none: none === "" ? 1 : 0,
		btn_partial: partial.length,
		btn_lines: lines.length,
		btn_bytes: bytes.length,
		btn_n: 4,
	};
}

function lispRightTrim(text) {
	return text.replace(/[ \t\n\r]+$/, "");
}

function replicaBashLiveOutputForMode(mode, frontend, tui, otherwise) {
	if (mode === "repl") return frontend;
	if (mode === "tui") return tui;
	return otherwise;
}

function replicaBashStripStatusFooter(text, status) {
	if (text === status) return "";
	if (text.length > status.length && text.endsWith(status)) {
		return lispRightTrim(text.slice(0, text.length - status.length));
	}
	return text;
}

function replicaBashStripTruncationFooter(text) {
	if (text.length === 0 || text[text.length - 1] !== "]") {
		return text;
	}
	const footerStart = text.lastIndexOf("\n\n[");
	if (footerStart < 0) {
		return text;
	}
	if (!text.includes("Full output: ", footerStart)) {
		return text;
	}
	return lispRightTrim(text.slice(0, footerStart));
}

function runBashLiveOutput() {
	const frontend = { id: "frontend" };
	const tui = { id: "tui" };
	const otherwise = { id: "otherwise" };
	const pick = replicaBashLiveOutputForMode;
	return {
		lo_repl: pick("repl", frontend, tui, otherwise) === frontend ? 1 : 0,
		lo_tui: pick("tui", frontend, tui, otherwise) === tui ? 1 : 0,
		lo_print: pick("print", frontend, tui, otherwise) === otherwise ? 1 : 0,
		lo_rpc: pick("rpc", frontend, tui, otherwise) === otherwise ? 1 : 0,
	};
}

function runBashStripStatusFooter() {
	const status = "Command aborted";
	const exact = replicaBashStripStatusFooter(status, status);
	const nl = replicaBashStripStatusFooter(`out\n\n${status}`, status);
	const plain = replicaBashStripStatusFooter("plain output", status);
	const trim = replicaBashStripStatusFooter(`keep  \n${status}`, status);
	return {
		ss_exact: exact === "" ? 1 : 0,
		ss_nl: nl === "out" ? 1 : 0,
		ss_plain: plain === "plain output" ? 1 : 0,
		ss_trim: trim === "keep" ? 1 : 0,
	};
}

function runBashStripTruncationFooter() {
	const none = replicaBashStripTruncationFooter("plain");
	const footer = replicaBashStripTruncationFooter(
		"keep\n\n[Showing last 1 of line 2. Full output: /tmp/x]",
	);
	const noFull = replicaBashStripTruncationFooter("keep\n\n[Showing last 1 of line 2.]");
	const plain = replicaBashStripTruncationFooter("");
	return {
		st_none: none === "plain" ? 1 : 0,
		st_footer: footer === "keep" ? 1 : 0,
		st_no_full: noFull === "keep\n\n[Showing last 1 of line 2.]" ? 1 : 0,
		st_plain: plain === "" ? 1 : 0,
	};
}

function leftoverProcessDeadline(timeout, nowMs = Date.now()) {
	if (timeout == null) return null;
	return nowMs + Math.round(timeout * 1000);
}

function leftoverUserBashResult(command, exclude, contentText, details) {
	const raw = contentText == null ? "" : contentText;
	const exitCode = details.exitCode;
	const withoutExit =
		typeof exitCode === "number" ? stripExitFooter(raw, exitCode) : raw;
	return {
		command,
		output: replicaBashStripTruncationFooter(withoutExit),
		exitCode,
		cancelledP: Boolean(details.cancelled),
		truncatedP: Boolean(details.truncated),
		fullOutputPath: details.fullOutputPath,
		excludeFromContextP: Boolean(exclude),
	};
}

function leftoverNormalizedExtension(result) {
	const output = result.output ?? "";
	const exitCode = result.exitCode ?? 0;
	const text = `${output}${output.length > 0 ? "\n" : ""}Process exited with code ${exitCode}`;
	return {
		text,
		exitCode,
		cancelled: result.cancelledP,
		truncated: result.truncatedP,
		fullOutputPath: result.fullOutputPath,
	};
}

function runBashProcessDeadline() {
	const none = leftoverProcessDeadline(null);
	const zero = leftoverProcessDeadline(0);
	const one = leftoverProcessDeadline(1);
	const two = leftoverProcessDeadline(2);
	return {
		pd_nil: none === null ? 1 : 0,
		pd_int: Number.isInteger(one) ? 1 : 0,
		pd_ord: Number.isInteger(one) && Number.isInteger(two) && one < two ? 1 : 0,
		pd_zero: Number.isInteger(zero) ? 1 : 0,
	};
}

function runBashUserBashResult() {
	const plain = leftoverUserBashResult("echo", false, "hello", { exitCode: 0 });
	const footer = leftoverUserBashResult("ls", false, "hi\nProcess exited with code 1", {
		exitCode: 1,
	});
	const empty = leftoverUserBashResult("true", false, null, { exitCode: 0 });
	const cancelled = leftoverUserBashResult("sleep", true, "x", {
		exitCode: null,
		cancelled: true,
	});
	const trunc = leftoverUserBashResult(
		"cat",
		false,
		"keep\n\n[Showing last 1 of line 2. Full output: /tmp/x]",
		{ exitCode: 0, truncated: true, fullOutputPath: "/tmp/x" },
	);
	return {
		ubr_cmd: plain.command === "echo" && plain.output === "hello" ? 1 : 0,
		ubr_out: footer.output === "hi" && footer.exitCode === 1 ? 1 : 0,
		ubr_exit: empty.output === "" ? 1 : 0,
		ubr_can: cancelled.cancelledP && cancelled.excludeFromContextP ? 1 : 0,
		ubr_ex: trunc.output === "keep" && trunc.truncatedP ? 1 : 0,
		ubr_n: 5,
	};
}

function runBashNormalizedExtension() {
	const hit = leftoverNormalizedExtension({
		output: "out",
		exitCode: 2,
		cancelledP: true,
		truncatedP: false,
		fullOutputPath: "/tmp/f",
	});
	const empty = leftoverNormalizedExtension({ output: "", exitCode: 0 });
	return {
		neb_text: hit.text === "out\nProcess exited with code 2" ? 1 : 0,
		neb_nl: empty.text === "Process exited with code 0" ? 1 : 0,
		neb_code: hit.exitCode === 2 ? 1 : 0,
		neb_can: hit.cancelled ? 1 : 0,
		neb_path: hit.fullOutputPath === "/tmp/f" ? 1 : 0,
		neb_n: 5,
	};
}

