function makeOutputAccumulatorBench() {
	return new outputAccumulatorModule.OutputAccumulator({
		maxLines: 50,
		maxBytes: 2048,
		tempFilePrefix: "oa-bench",
	});
}

function appendOutputAccumulatorCompleteChunks(accumulator) {
	accumulator.append(Buffer.from([0x68, 0x65, 0x6c, 0x6c, 0x6f, 0x0a]));
	accumulator.append(Buffer.from([0xc3]));
	accumulator.append(Buffer.from([0xa9, 0x20, 0x77, 0x6f, 0x72, 0x6c, 0x64, 0x0a]));
	accumulator.append(Buffer.from([0x74, 0x61, 0x69, 0x6c, 0x20, 0x6c, 0x69, 0x6e, 0x65]));
	return accumulator;
}

function runOutputAccumulatorAppend() {
	const accumulator = makeOutputAccumulatorBench();
	appendOutputAccumulatorCompleteChunks(accumulator);
	const snapshot = accumulator.snapshot();
	return {
		oa_append_bytes: Buffer.byteLength(snapshot.content, "utf8"),
		oa_append_trunc: snapshot.truncation.truncated ? 1 : 0,
		oa_append_lines: snapshot.truncation.totalLines,
		oa_append_last: accumulator.getLastLineBytes(),
		oa_append_n: 4,
	};
}

function runOutputAccumulatorSnapshot() {
	const accumulator = makeOutputAccumulatorBench();
	appendOutputAccumulatorCompleteChunks(accumulator);
	const snapshot = accumulator.snapshot();
	return {
		oa_snap_bytes: Buffer.byteLength(snapshot.content, "utf8"),
		oa_snap_trunc: snapshot.truncation.truncated ? 1 : 0,
		oa_snap_lines: snapshot.truncation.totalLines,
		oa_snap_total: snapshot.truncation.totalBytes,
		oa_snap_n: 4,
	};
}

function runOutputAccumulatorFinish() {
	const accumulator = makeOutputAccumulatorBench();
	accumulator.append(Buffer.from([0xc3]));
	accumulator.finish();
	const snapshot = accumulator.snapshot();
	return {
		oa_fin_bytes: Buffer.byteLength(snapshot.content, "utf8"),
		oa_fin_fffd: snapshot.content.includes("\uFFFD") ? 1 : 0,
		oa_fin_last: accumulator.getLastLineBytes(),
		oa_fin_trunc: snapshot.truncation.truncated ? 1 : 0,
		oa_fin_n: 4,
	};
}

function runOutputAccumulatorLastLineBytes() {
	const openLine = makeOutputAccumulatorBench();
	const closedLine = makeOutputAccumulatorBench();
	const utf8Line = makeOutputAccumulatorBench();
	openLine.append(Buffer.from([0x68, 0x65, 0x6c, 0x6c, 0x6f]));
	closedLine.append(Buffer.from([0x68, 0x65, 0x6c, 0x6c, 0x6f, 0x0a]));
	utf8Line.append(Buffer.from([0xc3, 0xa9]));
	return {
		oa_ll_open: openLine.getLastLineBytes(),
		oa_ll_nl: closedLine.getLastLineBytes(),
		oa_ll_utf8: utf8Line.getLastLineBytes(),
		oa_ll_n: 3,
	};
}

function makeOutputAccumulatorNeeds() {
	return new outputAccumulatorModule.OutputAccumulator({
		maxLines: 2,
		maxBytes: 16,
		tempFilePrefix: "oa-needs",
	});
}

function oaNeedsFile(accumulator) {
	return accumulator.shouldUseTempFile() ? 1 : 0;
}

function runOutputAccumulatorNeedsFile() {
	const empty = makeOutputAccumulatorNeeds();
	const under = makeOutputAccumulatorNeeds();
	const overBytes = makeOutputAccumulatorNeeds();
	const overLines = makeOutputAccumulatorNeeds();
	under.append(Buffer.from([0x68, 0x69]));
	overBytes.append(Buffer.alloc(20, 0x78));
	overLines.append(Buffer.from([0x61, 0x0a, 0x62, 0x0a, 0x63, 0x0a]));
	return {
		oa_nf_empty: oaNeedsFile(empty),
		oa_nf_under: oaNeedsFile(under),
		oa_nf_bytes: oaNeedsFile(overBytes),
		oa_nf_lines: oaNeedsFile(overLines),
		oa_nf_n: 4,
	};
}

async function runOutputAccumulatorCloseTempFile() {
	const accumulator = new outputAccumulatorModule.OutputAccumulator({
		maxLines: 50,
		maxBytes: 16,
		tempFilePrefix: "oa-close",
	});
	accumulator.append(Buffer.alloc(32, 0x78));
	const path = accumulator.tempFilePath;
	await accumulator.closeTempFile();
	const pathOk = path && existsSync(path) ? 1 : 0;
	const streamClosed = accumulator.tempFileStream ? 0 : 1;
	if (path && existsSync(path)) unlinkSync(path);
	return {
		oa_close_path: pathOk,
		oa_close_stream: streamClosed,
		oa_close_n: 1,
	};
}

async function measureOutputAccumulator() {
	const appendObserved = runOutputAccumulatorAppend();
	const snapshotObserved = runOutputAccumulatorSnapshot();
	const finishObserved = runOutputAccumulatorFinish();
	const lastObserved = runOutputAccumulatorLastLineBytes();
	const needsObserved = runOutputAccumulatorNeedsFile();
	const closeObserved = await runOutputAccumulatorCloseTempFile();
	return {
		append: await collect("output_accumulator.append", () => {
			return () => runOutputAccumulatorAppend();
		}),
		snapshot: await collect("output_accumulator.snapshot", () => {
			return () => runOutputAccumulatorSnapshot();
		}),
		finish: await collect("output_accumulator.finish", () => {
			return () => runOutputAccumulatorFinish();
		}),
		last_line_bytes: await collect("output_accumulator.last_line_bytes", () => {
			return () => runOutputAccumulatorLastLineBytes();
		}),
		needs_file: await collect("output_accumulator.needs_file", () => {
			return () => runOutputAccumulatorNeedsFile();
		}),
		close_temp_file: await collect("output_accumulator.close_temp_file", () => {
			return () => runOutputAccumulatorCloseTempFile();
		}),
		observed: {
			...appendObserved,
			...snapshotObserved,
			...finishObserved,
			...lastObserved,
			...needsObserved,
			...closeObserved,
		},
	};
}

function tmTruth(value) {
	return value ? 1 : 0;
}

function tmWriteStub(directory, name) {
	mkdirSync(directory, { recursive: true });
	const filePath = path.join(directory, name);
	writeFileSync(filePath, "stub");
	return filePath;
}

function tmDeleteIfExists(filePath) {
	if (existsSync(filePath)) unlinkSync(filePath);
}

function tmWithEmptyPath(fn) {
	const previous = process.env.PATH;
	process.env.PATH = "/nonexistent-goal20-tool-manager";
	try {
		return fn();
	} finally {
		if (previous === undefined) delete process.env.PATH;
		else process.env.PATH = previous;
	}
}

let toolsManagerModulePromise;
async function loadToolsManager() {
	if (!toolsManagerModulePromise) {
		process.env[configModule.ENV_AGENT_DIR] = agentDirectory;
		toolsManagerModulePromise = import(moduleUrl("packages/coding-agent/src/utils/tools-manager.ts"));
	}
	return toolsManagerModulePromise;
}

function tmAgentBin() {
	return path.join(agentDirectory, "bin");
}

function tmIsLocalBinary(result, name) {
	return Boolean(
		result &&
			path.isAbsolute(result) &&
			path.basename(result) === name,
	);
}

function runToolManagerGetToolPath(toolsManager) {
	const toolsDir = tmAgentBin();
	mkdirSync(toolsDir, { recursive: true });
	const fd = tmWriteStub(toolsDir, "fd");
	const rg = tmWriteStub(toolsDir, "rg");
	const localFd = toolsManager.getToolPath("fd");
	const localRg = toolsManager.getToolPath("rg");
	tmDeleteIfExists(fd);
	tmDeleteIfExists(rg);
	const missFd = tmWithEmptyPath(() => toolsManager.getToolPath("fd"));
	const missRg = tmWithEmptyPath(() => toolsManager.getToolPath("rg"));
	return {
		gtp_local_fd: tmTruth(tmIsLocalBinary(localFd, "fd")),
		gtp_local_rg: tmTruth(tmIsLocalBinary(localRg, "rg")),
		gtp_miss_fd: tmTruth(missFd == null),
		gtp_miss_rg: tmTruth(missRg == null),
		gtp_n: 4,
	};
}

async function runToolManagerEnsureTool(toolsManager) {
	const toolsDir = tmAgentBin();
	mkdirSync(toolsDir, { recursive: true });
	const fd = tmWriteStub(toolsDir, "fd");
	const local = await toolsManager.ensureTool("fd");
	tmDeleteIfExists(fd);
	const previousOffline = process.env.PI_OFFLINE;
	const previousPath = process.env.PATH;
	let offline;
	process.env.PI_OFFLINE = "1";
	process.env.PATH = "/nonexistent-goal20-tool-manager";
	try {
		offline = await toolsManager.ensureTool("fd");
	} finally {
		if (previousPath === undefined) delete process.env.PATH;
		else process.env.PATH = previousPath;
		if (previousOffline === undefined) delete process.env.PI_OFFLINE;
		else process.env.PI_OFFLINE = previousOffline;
	}
	return {
		et_local_fd: tmTruth(tmIsLocalBinary(local, "fd")),
		et_offline_miss: tmTruth(offline == null),
		et_n: 2,
	};
}

function runToolManagerCleanupQuarantine() {
	const root = path.join(scratch, "tool-manager-pkg");
	const nodeModules = path.join(root, "node_modules");
	const pkg = path.join(nodeModules, "pkg");
	const quarantine = path.join(nodeModules, ".pi-native-quarantine");
	const outside = path.join(scratch, "no-modules", "pkg");
	mkdirSync(pkg, { recursive: true });
	mkdirSync(quarantine, { recursive: true });
	writeFileSync(path.join(quarantine, "stale.bin"), "stub");
	windowsSelfUpdateModule.cleanupWindowsSelfUpdateQuarantine(pkg);
	const removed = tmTruth(!existsSync(quarantine));
	mkdirSync(outside, { recursive: true });
	windowsSelfUpdateModule.cleanupWindowsSelfUpdateQuarantine(outside);
	return {
		cq_removed: removed,
		cq_noop: 1,
		cq_n: 2,
	};
}

// Baseline tools-manager.ts TOOLS.getAssetName is unexported; keep the
// production algorithm here so the pair times the same asset names.
function toolReleaseAsset(tool, version, plat, architecture) {
	const archStr = architecture === "arm64" ? "aarch64" : "x86_64";
	if (tool === "fd") {
		if (plat === "darwin") return `fd-v${version}-${archStr}-apple-darwin.tar.gz`;
		if (plat === "linux") return `fd-v${version}-${archStr}-unknown-linux-gnu.tar.gz`;
		if (plat === "win32") return `fd-v${version}-${archStr}-pc-windows-msvc.zip`;
		return null;
	}
	if (tool === "rg") {
		if (plat === "darwin") return `ripgrep-${version}-${archStr}-apple-darwin.tar.gz`;
		if (plat === "linux") {
			if (architecture === "arm64") {
				return `ripgrep-${version}-aarch64-unknown-linux-gnu.tar.gz`;
			}
			return `ripgrep-${version}-x86_64-unknown-linux-musl.tar.gz`;
		}
		if (plat === "win32") return `ripgrep-${version}-${archStr}-pc-windows-msvc.zip`;
		return null;
	}
	return null;
}

function tmAssetFlag(tool, version, plat, architecture, expected) {
	return toolReleaseAsset(tool, version, plat, architecture) === expected ? 1 : 0;
}

function runToolManagerReleaseAsset() {
	return {
		ra_fd_darwin_arm: tmAssetFlag(
			"fd",
			"10.2.0",
			"darwin",
			"arm64",
			"fd-v10.2.0-aarch64-apple-darwin.tar.gz",
		),
		ra_fd_linux_x64: tmAssetFlag(
			"fd",
			"10.2.0",
			"linux",
			"x64",
			"fd-v10.2.0-x86_64-unknown-linux-gnu.tar.gz",
		),
		ra_fd_win_x64: tmAssetFlag(
			"fd",
			"10.2.0",
			"win32",
			"x64",
			"fd-v10.2.0-x86_64-pc-windows-msvc.zip",
		),
		ra_rg_linux_x64: tmAssetFlag(
			"rg",
			"14.1.0",
			"linux",
			"x64",
			"ripgrep-14.1.0-x86_64-unknown-linux-musl.tar.gz",
		),
		ra_rg_linux_arm: tmAssetFlag(
			"rg",
			"14.1.0",
			"linux",
			"arm64",
			"ripgrep-14.1.0-aarch64-unknown-linux-gnu.tar.gz",
		),
		ra_rg_darwin_arm: tmAssetFlag(
			"rg",
			"14.1.0",
			"darwin",
			"arm64",
			"ripgrep-14.1.0-aarch64-apple-darwin.tar.gz",
		),
		ra_n: 6,
	};
}

function findBinaryRecursively(rootDir, binaryFileName) {
	const stack = [rootDir];
	while (stack.length > 0) {
		const currentDir = stack.pop();
		if (!currentDir) continue;
		const entries = readdirSync(currentDir, { withFileTypes: true });
		for (const entry of entries) {
			const fullPath = path.join(currentDir, entry.name);
			if (entry.isFile() && entry.name === binaryFileName) {
				return fullPath;
			}
			if (entry.isDirectory()) {
				stack.push(fullPath);
			}
		}
	}
	return null;
}

function runToolManagerFindBinary() {
	const extract = path.join(scratch, "tool-manager-extract");
	const nested = path.join(extract, "nested", "bin");
	rmSync(extract, { recursive: true, force: true });
	mkdirSync(nested, { recursive: true });
	writeFileSync(path.join(nested, "fd"), "stub");
	writeFileSync(path.join(extract, "rg"), "stub");
	const nestedFd = findBinaryRecursively(extract, "fd");
	const rootRg = findBinaryRecursively(extract, "rg");
	const miss = findBinaryRecursively(extract, "missing-bin");
	return {
		fb_nested: tmTruth(nestedFd && path.basename(nestedFd) === "fd"),
		fb_root: tmTruth(rootRg && path.basename(rootRg) === "rg"),
		fb_miss: tmTruth(miss == null),
		fb_n: 3,
	};
}

function runToolManagerQuarantineNative() {
	const root = path.join(scratch, "tool-manager-qn");
	const nodeModules = path.join(root, "node_modules");
	const pkg = path.join(nodeModules, "pkg");
	const native = path.join(pkg, "native.so");
	const quarantine = path.join(nodeModules, ".pi-native-quarantine");
	const outsideRoot = path.join(scratch, "no-modules-qn");
	const outside = path.join(outsideRoot, "pkg");
	const outsideNative = path.join(outside, "native.so");
	const outsideQuarantine = path.join(outsideRoot, ".pi-native-quarantine");
	rmSync(root, { recursive: true, force: true });
	rmSync(outsideRoot, { recursive: true, force: true });
	mkdirSync(pkg, { recursive: true });
	mkdirSync(outside, { recursive: true });
	writeFileSync(native, "stub");
	writeFileSync(outsideNative, "stub");
	const originalGetReport = process.report.getReport;
	process.report.getReport = () => ({ sharedObjects: [native] });
	try {
		windowsSelfUpdateModule.quarantineWindowsNativeDependencies(pkg);
	} finally {
		process.report.getReport = originalGetReport;
	}
	const restored = tmTruth(existsSync(native));
	const stashed = tmTruth(
		existsSync(quarantine) && findBinaryRecursively(quarantine, "native.so"),
	);
	process.report.getReport = () => ({ sharedObjects: [outsideNative] });
	try {
		windowsSelfUpdateModule.quarantineWindowsNativeDependencies(outside);
	} finally {
		process.report.getReport = originalGetReport;
	}
	return {
		qn_restored: restored,
		qn_stashed: stashed,
		qn_noop: tmTruth(existsSync(outsideNative) && !existsSync(outsideQuarantine)),
		qn_n: 3,
	};
}

