function packageSourceFixtureInputs() {
	return [
		"npm:@scope/pkg@1.2.3",
		"npm:@scope/pkg@^1.2.3",
		"https://github.com/user/repo",
		"ssh://git@github.com/user/repo",
		"git:git@github.com:user/repo",
		"git:github.com/user/repo",
		"https://github.com/user/repo.git",
		"git:git@github.com:user/repo@v1.0.0",
		"./relative/package",
		"../relative/package",
		"git@github.com:user/repo",
		"github.com/user/repo",
	];
}

function runPackageManagerPackageSource() {
	const manager = makePackageManager();
	const internals = manager;
	let npmPinned = 0;
	let npmRange = 0;
	let git = 0;
	let gitPinned = 0;
	let local = 0;
	let gitIdOk = 1;
	let refOk = 0;
	for (const input of packageSourceFixtureInputs()) {
		const parsed = internals.parseSource(input);
		if (parsed.type === "npm") {
			if (parsed.pinned) {
				npmPinned += 1;
			} else {
				npmRange += 1;
			}
		} else if (parsed.type === "git") {
			if (parsed.pinned) {
				gitPinned += 1;
				if (parsed.ref === "v1.0.0") {
					refOk = 1;
				}
			} else {
				git += 1;
				if (internals.getPackageIdentity(input) !== "git:github.com/user/repo") {
					gitIdOk = 0;
				}
			}
		} else {
			local += 1;
		}
	}
	const deduped = internals.dedupePackages([
		{ pkg: "https://github.com/user/repo", scope: "user" },
		{ pkg: "ssh://git@github.com/user/repo@main", scope: "project" },
	]);
	return {
		ps_npm_pin: npmPinned,
		ps_npm_rng: npmRange,
		ps_git: git,
		ps_git_pin: gitPinned,
		ps_local: local,
		ps_ref_ok: refOk,
		ps_git_id: gitIdOk,
		ps_ded_n: deduped.length,
		ps_ded_proj: deduped.length > 0 && deduped[0]?.scope === "project" ? 1 : 0,
	};
}

function toPosixPath(value) {
	return value.split(path.sep).join("/");
}

function normalizeExactPattern(pattern) {
	const normalized =
		pattern.startsWith("./") || pattern.startsWith(".\\")
			? pattern.slice(2)
			: pattern;
	return toPosixPath(normalized);
}

function runPackageManagerNormalizePattern() {
	return {
		np_dot: normalizeExactPattern("./foo") === "foo" ? 1 : 0,
		np_plain: normalizeExactPattern("bar") === "bar" ? 1 : 0,
		np_win: normalizeExactPattern(".\\baz") === "baz" ? 1 : 0,
	};
}

