const PACKAGE_RESOURCE_SPECIFICATIONS = [
	["extensions", "extensions/", "lisp", null],
	["skills", "skills/", null, "SKILL.md"],
	["prompts", "prompts/", "md", null],
	["themes", "themes/", "json", null],
];

function leftoverConfigResourceSpecification(type) {
	const spec = PACKAGE_RESOURCE_SPECIFICATIONS.find((entry) => entry[0] === type);
	if (!spec) {
		throw new Error(`Unknown config resource type: ${type}`);
	}
	return spec;
}

function leftoverConfigNormalizePatternPath(value) {
	const normalized = value.replaceAll("\\", "/");
	return normalized.startsWith("./") ? normalized.slice(2) : normalized;
}

function leftoverConfigGlobRegex(pattern) {
	let out = "^";
	const escaped = ".+()[]{}^$|\\";
	for (const character of leftoverConfigNormalizePatternPath(pattern)) {
		if (character === "*") {
			out += "[^/]*";
		} else if (character === "?") {
			out += "[^/]";
		} else if (escaped.includes(character)) {
			out += `\\${character}`;
		} else {
			out += character;
		}
	}
	return `${out}$`;
}

function leftoverFileNamestring(filePath) {
	const parts = filePath.replaceAll("\\", "/").split("/").filter(Boolean);
	return parts[parts.length - 1] ?? "";
}

function leftoverPathnameDirectoryPathname(filePath) {
	const file = filePath.replaceAll("\\", "/");
	const idx = file.lastIndexOf("/");
	if (idx < 0) {
		return "./";
	}
	return leftoverEnsureDir(file.slice(0, idx + 1));
}

function leftoverConfigPatternCandidates(path, baseDirectory = "/tmp/") {
	const absolute = leftoverConfigNormalizePatternPath(path);
	const relative = leftoverConfigNormalizePatternPath(
		leftoverConfigSelectorRelativePattern(path, baseDirectory),
	);
	const name = leftoverFileNamestring(path);
	const out = [];
	const push = (value) => {
		if (!out.includes(value)) {
			out.push(value);
		}
	};
	push(relative);
	push(name);
	push(absolute);
	if (name === "SKILL.md") {
		const parent = leftoverPathnameDirectoryPathname(path);
		push(
			leftoverConfigNormalizePatternPath(
				leftoverConfigSelectorRelativePattern(parent, baseDirectory).replace(
					/\/+$/,
					"",
				),
			),
		);
		const parts = parent.replace(/\/+$/, "").split("/").filter(Boolean);
		push(parts[parts.length - 1] ?? "");
		push(leftoverConfigNormalizePatternPath(parent.replace(/\/+$/, "")));
	}
	return out;
}

function leftoverConfigPatternMatchesP(path, pattern, baseDirectory, exactP = false) {
	const normalized = leftoverConfigNormalizePatternPath(pattern);
	const candidates = leftoverConfigPatternCandidates(path, baseDirectory);
	if (exactP) {
		return candidates.includes(normalized);
	}
	const re = new RegExp(leftoverConfigGlobRegex(normalized));
	return candidates.some((candidate) => re.test(candidate));
}

function leftoverConfigEnabledByPatternsP(
	path,
	patterns,
	baseDirectory,
	defaultEnabled = true,
) {
	const includes = [];
	const excludes = [];
	const loads = [];
	const unloads = [];
	for (const pattern of patterns) {
		if (typeof pattern !== "string" || pattern.length === 0) {
			continue;
		}
		switch (pattern[0]) {
			case "+":
				loads.push(pattern.slice(1));
				break;
			case "-":
				unloads.push(pattern.slice(1));
				break;
			case "!":
				excludes.push(pattern.slice(1));
				break;
			default:
				includes.push(pattern);
		}
	}
	let enabled = includes.length
		? includes.some((entry) => leftoverConfigPatternMatchesP(path, entry, baseDirectory))
		: defaultEnabled;
	if (
		excludes.some((entry) => leftoverConfigPatternMatchesP(path, entry, baseDirectory))
	) {
		enabled = false;
	}
	if (
		loads.some((entry) => leftoverConfigPatternMatchesP(path, entry, baseDirectory, true))
	) {
		enabled = true;
	}
	if (
		unloads.some((entry) => leftoverConfigPatternMatchesP(path, entry, baseDirectory, true))
	) {
		enabled = false;
	}
	return Boolean(enabled);
}

function leftoverConfigPackageDeltaResourceState(path, patterns, rootDir) {
	let matchedP = false;
	let enabledP = false;
	const root = leftoverEnsureDir(rootDir || "");
	for (const pattern of patterns || []) {
		if (typeof pattern !== "string" || pattern.length === 0) {
			continue;
		}
		const prefix = pattern[0];
		const target = leftoverConfigSelectorEntryTarget(pattern);
		const exactP = prefix === "+" || prefix === "-";
		if (leftoverConfigPatternMatchesP(path, target, root, exactP)) {
			matchedP = true;
			enabledP = prefix !== "-" && prefix !== "!";
		}
	}
	return [enabledP, matchedP];
}

function leftoverConfigDeltaCode(enabledP, matchedP) {
	return (enabledP ? 1 : 0) * 10 + (matchedP ? 1 : 0);
}

function leftoverConfigSelectorStateCode(state) {
	if (state === "inherit") {
		return 0;
	}
	if (state === "load") {
		return 1;
	}
	if (state === "unload") {
		return 2;
	}
	return -1;
}

function leftoverPackageSourceIdentity(source) {
	const trimmed = String(source ?? "");
	if (trimmed.startsWith("npm:")) {
		const rest = trimmed.slice(4);
		if (rest.startsWith("@")) {
			const slash = rest.indexOf("/");
			if (slash === -1) {
				return `npm:${rest}`;
			}
			const after = rest.slice(slash + 1);
			const versionAt = after.lastIndexOf("@");
			const name = versionAt === -1 ? rest : rest.slice(0, slash + 1 + versionAt);
			return `npm:${name}`;
		}
		const at = rest.lastIndexOf("@");
		return `npm:${at > 0 ? rest.slice(0, at) : rest}`;
	}
	return trimmed;
}

function leftoverSettingsPackageEntries(manager, scope) {
	const object = scope === "project" ? manager?.project : manager?.global;
	const value = object?.packages;
	return Array.isArray(value) ? value.slice() : [];
}

