function leftoverConfigPackageEntryFilter(entry, type) {
	if (entry == null || typeof entry !== "object" || Array.isArray(entry)) {
		return null;
	}
	if (!Object.prototype.hasOwnProperty.call(entry, type)) {
		return null;
	}
	const value = entry[type];
	if (Array.isArray(value)) {
		return value.slice();
	}
	return null;
}

