function leftoverPackageSourceIsLocal(source) {
	const trimmed = String(source).replace(/^[\s\t\n\r]+|[\s\t\n\r]+$/g, "");
	if (trimmed.startsWith("npm:")) {
		return false;
	}
	if (trimmed.startsWith("git:")) {
		return false;
	}
	if (/^(https?:\/\/|git@)/i.test(trimmed)) {
		return false;
	}
	return true;
}

