function percentDecode(value) {
	return decodeURIComponent(String(value).replace(/\+/g, " "));
}

function percentDecodeFlag(encoded, expected) {
	try {
		return percentDecode(encoded) === expected ? 1 : 0;
	} catch {
		return 0;
	}
}

