const LOADER_DEFAULT_FRAMES = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
const LOADER_DEFAULT_INTERVAL_MS = 80;

function loaderFrames(indicatorFrames) {
	return indicatorFrames !== undefined ? [...indicatorFrames] : [...LOADER_DEFAULT_FRAMES];
}

function loaderIntervalMs(intervalMs) {
	return intervalMs && intervalMs > 0 ? intervalMs : LOADER_DEFAULT_INTERVAL_MS;
}

function runTuiLoaderFrames() {
	const defaults = loaderFrames(undefined);
	const custom = loaderFrames(["a", "b"]);
	const one = loaderFrames(["x"]);
	return {
		lf_default_n: defaults.length,
		lf_default_first: defaults[0] === "⠋" ? 1 : 0,
		lf_custom_n: custom.length,
		lf_one_n: one.length,
	};
}

function runTuiLoaderInterval() {
	return {
		li_default: loaderIntervalMs(undefined),
		li_pos: loaderIntervalMs(200),
		li_zero: loaderIntervalMs(0),
		li_n: 3,
	};
}

function makeStoppedBenchLoader() {
	const ui = { requestRender() {} };
	const loader = new loaderModule.Loader(ui, (text) => text, (text) => text, "Loading...", {
		frames: ["a", "b"],
	});
	loader.stop();
	return loader;
}

function loaderStep(loader) {
	const frames = loader.frames;
	loader.currentFrame = (loader.currentFrame + 1) % frames.length;
	loader.updateDisplay();
}

function loaderTextHas(loader, needle) {
	return typeof loader.text === "string" && loader.text.includes(needle) ? 1 : 0;
}

function runTuiLoaderStep() {
	const loader = makeStoppedBenchLoader();
	const initial = loaderTextHas(loader, "a Loading...");
	loaderStep(loader);
	const next = loaderTextHas(loader, "b Loading...");
	loaderStep(loader);
	return {
		ls_initial: initial,
		ls_next: next,
		ls_wrap: loaderTextHas(loader, "a Loading..."),
		ls_n: 3,
	};
}

function runTuiLoaderMake() {
	const loader = makeStoppedBenchLoader();
	const hasA = loaderTextHas(loader, "a Loading...");
	const nframes = loader.frames.length;
	loader.stop();
	return { ml_has_a: hasA, ml_frames: nframes, ml_n: 2 };
}


function runTuiLoaderSetMessage() {
	const loader = makeStoppedBenchLoader();
	loader.setMessage("Working");
	const working = loaderTextHas(loader, "Working");
	const kept = loaderTextHas(loader, "a ");
	loader.stop();
	return { sm_working: working, sm_kept_a: kept, sm_n: 2 };
}


function runTuiLoaderSetIndicator() {
	const loader = makeStoppedBenchLoader();
	loader.setIndicator({ frames: ["x", "y"], intervalMs: 200 });
	loader.stop();
	const hasX = loaderTextHas(loader, "x Loading...");
	const nframes = loader.frames.length;
	return { si_has_x: hasX, si_frames: nframes, si_n: 2 };
}


function makeStoppedCancellableLoader(frames = ["a", "b"], message = "Loading...") {
	const ui = { requestRender() {} };
	const loader = new cancellableLoaderModule.CancellableLoader(
		ui,
		(text) => text,
		(text) => text,
		message,
		{ frames },
	);
	loader.stop();
	return loader;
}


function runTuiLoaderUpdateDisplay() {
	const loader = makeStoppedBenchLoader();
	loader.updateDisplay();
	const hasA = loaderTextHas(loader, "a Loading...");
	const nframes = loader.frames.length;
	loader.stop();
	return { ud_has_a: hasA, ud_frames: nframes, ud_n: 2 };
}


function runTuiLoaderMakeCancellable() {
	const loader = makeStoppedCancellableLoader();
	const hasA = loaderTextHas(loader, "a Loading...");
	const aborted = loader.aborted ? 1 : 0;
	loader.stop();
	return { cl_has_a: hasA, cl_aborted: aborted, cl_n: 2 };
}


function runTuiLoaderAborted() {
	const loader = makeStoppedCancellableLoader();
	const before = loader.aborted ? 1 : 0;
	loader.abortController.abort();
	const after = loader.aborted ? 1 : 0;
	loader.stop();
	return { ct_before: before, ct_after: after, ct_n: 2 };
}


