const ARMIN_WIDTH = 31;
const ARMIN_HEIGHT = 36;
const ARMIN_BITS = Uint8Array.from([
	0xff, 0xff, 0xff, 0x7f, 0xff, 0xf0, 0xff, 0x7f, 0xff, 0xed, 0xff, 0x7f,
	0xff, 0xdb, 0xff, 0x7f, 0xff, 0xb7, 0xff, 0x7f, 0xff, 0x77, 0xfe, 0x7f,
	0x3f, 0xf8, 0xfe, 0x7f, 0xdf, 0xff, 0xfe, 0x7f, 0xdf, 0x3f, 0xfc, 0x7f,
	0x9f, 0xc3, 0xfb, 0x7f, 0x6f, 0xfc, 0xf4, 0x7f, 0xf7, 0x0f, 0xf7, 0x7f,
	0xf7, 0xff, 0xf7, 0x7f, 0xf7, 0xff, 0xe3, 0x7f, 0xf7, 0x07, 0xe8, 0x7f,
	0xef, 0xf8, 0x67, 0x70, 0x0f, 0xff, 0xbb, 0x6f, 0xf1, 0x00, 0xd0, 0x5b,
	0xfd, 0x3f, 0xec, 0x53, 0xc1, 0xff, 0xef, 0x57, 0x9f, 0xfd, 0xee, 0x5f,
	0x9f, 0xfc, 0xae, 0x5f, 0x1f, 0x78, 0xac, 0x5f, 0x3f, 0x00, 0x50, 0x6c,
	0x7f, 0x00, 0xdc, 0x77, 0xff, 0xc0, 0x3f, 0x78, 0xff, 0x01, 0xf8, 0x7f,
	0xff, 0x03, 0x9c, 0x78, 0xff, 0x07, 0x8c, 0x7c, 0xff, 0x0f, 0xce, 0x78,
	0xff, 0xff, 0xcf, 0x7f, 0xff, 0xff, 0xcf, 0x78, 0xff, 0xff, 0xdf, 0x78,
	0xff, 0xff, 0xdf, 0x7d, 0xff, 0xff, 0x3f, 0x7e, 0xff, 0xff, 0xff, 0x7f,
]);

function replicaArminPixelP(x, y) {
	if (y >= ARMIN_HEIGHT) {
		return null;
	}
	const bytesPerRow = Math.ceil(ARMIN_WIDTH / 8);
	const byte = ARMIN_BITS[y * bytesPerRow + Math.floor(x / 8)];
	return (byte & (1 << (x % 8))) === 0;
}

function replicaArminCell(x, row) {
	const upper = replicaArminPixelP(x, row * 2);
	const lower = replicaArminPixelP(x, 1 + row * 2);
	if (upper && lower) {
		return "█";
	}
	if (upper) {
		return "▀";
	}
	if (lower) {
		return "▄";
	}
	return " ";
}

function replicaArminGridHeight() {
	return Math.ceil(ARMIN_HEIGHT / 2);
}

function runCliSelectorsArminPixel() {
	return {
		ap_blank: replicaArminPixelP(0, 0) ? 1 : 0,
		ap_ink: replicaArminPixelP(8, 1) ? 1 : 0,
		ap_out: replicaArminPixelP(0, 36) ? 1 : 0,
	};
}

function runCliSelectorsArminCell() {
	return {
		ac_space: replicaArminCell(0, 0),
		ac_lower: replicaArminCell(8, 0),
		ac_upper: replicaArminCell(9, 1),
		ac_full: replicaArminCell(11, 2),
	};
}

function runCliSelectorsArminGridHeight() {
	return {
		ag_h: replicaArminGridHeight(),
	};
}

let cachedDaxnutsHex;
let cachedDaxnutsPixels;

function daxnutsHex() {
	if (cachedDaxnutsHex === undefined) {
		const source = readFileSync(
			path.join(
				baselineDirectory,
				"packages/coding-agent/src/modes/interactive/components/daxnuts.ts",
			),
			"utf8",
		);
		const match = source.match(/const DAX_HEX =\s*"([0-9a-f]+)"/);
		if (!match) {
			throw new Error("baseline daxnuts.ts DAX_HEX not found");
		}
		cachedDaxnutsHex = match[1];
	}
	return cachedDaxnutsHex;
}


function daxnutsParseImage(hex) {
	const width = 32;
	const height = 32;
	const pixels = [];
	for (let y = 0; y < height; y++) {
		const row = [];
		for (let x = 0; x < width; x++) {
			const idx = (y * width + x) * 6;
			const r = parseInt(hex.slice(idx, idx + 2), 16);
			const g = parseInt(hex.slice(idx + 2, idx + 4), 16);
			const b = parseInt(hex.slice(idx + 4, idx + 6), 16);
			row.push([r, g, b]);
		}
		pixels.push(row);
	}
	return pixels;
}


function daxnutsRgbEncode(rgb) {
	return `${rgb[0]},${rgb[1]},${rgb[2]}`;
}


function runCliSelectorsDaxnutsParseImage() {
	const pixels = daxnutsParseImage(daxnutsHex());
	return {
		dpi_00: daxnutsRgbEncode(pixels[0][0]),
		dpi_0x: daxnutsRgbEncode(pixels[0][31]),
		dpi_mid: daxnutsRgbEncode(pixels[16][16]),
		dpi_last: daxnutsRgbEncode(pixels[31][31]),
		dpi_h: String(pixels.length),
		dpi_w: String(pixels[0].length),
	};
}


function daxnutsPixelsCached() {
	if (cachedDaxnutsPixels === undefined) {
		cachedDaxnutsPixels = daxnutsParseImage(daxnutsHex());
	}
	return cachedDaxnutsPixels;
}


function daxnutsRgb(r, g, b, bg = false) {
	return `\x1b[${bg ? 48 : 38};2;${r};${g};${b}m`;
}


function daxnutsImageLine(row, pixels) {
	const width = 32;
	let line = "";
	const topRow = row * 2;
	const bottomRow = topRow + 1;
	for (let x = 0; x < width; x++) {
		const top = pixels[topRow][x];
		const bottom = pixels[bottomRow]?.[x] ?? top;
		line += `${daxnutsRgb(bottom[0], bottom[1], bottom[2])}${daxnutsRgb(top[0], top[1], top[2], true)}▄`;
	}
	line += "\x1b[0m";
	return line;
}


function runCliSelectorsDaxnutsImageLine() {
	const pixels = daxnutsPixelsCached();
	const line0 = daxnutsImageLine(0, pixels);
	const line7 = daxnutsImageLine(7, pixels);
	const line15 = daxnutsImageLine(15, pixels);
	return {
		dil_0: line0,
		dil_7: line7,
		dil_15: line15,
		dil_0_len: String(line0.length),
		dil_15_len: String(line15.length),
		dil_reset: line0.slice(-4),
	};
}


function daxnutsCenter(s, width) {
	const visible = s.replace(/\x1b\[[0-9;]*m/g, "").length;
	const left = Math.max(0, Math.floor((width - visible) / 2));
	return " ".repeat(left) + s;
}


function runCliSelectorsDaxnutsCenterLine() {
	return {
		dcl_plain: daxnutsCenter("hello", 20),
		dcl_odd: daxnutsCenter("x", 10),
		dcl_narrow: daxnutsCenter("hello", 3),
		dcl_empty: daxnutsCenter("", 10),
		dcl_ansi: daxnutsCenter("\x1b[31mhi\x1b[0m", 10),
		dcl_wide: daxnutsCenter("hi", 80),
	};
}


function leftoverDaxnutsBenchUi() {
	return {
		renders: 0,
		requestRender() {
			this.renders += 1;
		},
	};
}


function leftoverDaxnutsTick(state) {
	if (state.tick < state.maxTicks) {
		state.tick += 1;
		if (state.tick >= state.maxTicks) {
			state.stopped = true;
		}
		state.cachedWidth = 0;
		state.ui.requestRender();
	}
	return state;
}


function leftoverMakeDaxnutsComponentState(ui) {
	return {
		ui,
		tick: 0,
		maxTicks: 25,
		interval: null,
		cachedWidth: 0,
		stopped: false,
	};
}


function runCliSelectorsDaxnutsRgbAt() {
	const pixels = daxnutsPixelsCached();
	return {
		dra_00: daxnutsRgbEncode(pixels[0][0]),
		dra_0x: daxnutsRgbEncode(pixels[0][31]),
		dra_mid: daxnutsRgbEncode(pixels[16][16]),
		dra_last: daxnutsRgbEncode(pixels[31][31]),
		dra_10: daxnutsRgbEncode(pixels[1][0]),
	};
}


function runCliSelectorsMakeDaxnutsComponent() {
	const ui = leftoverDaxnutsBenchUi();
	const first = leftoverMakeDaxnutsComponentState(ui);
	const second = leftoverMakeDaxnutsComponentState(ui);
	return {
		dmc_tick: String(first.tick),
		dmc_stop: first.stopped ? "1" : "0",
		dmc_thread: first.interval ? "1" : "0",
		dmc_cache: first.cachedWidth ? "1" : "0",
		dmc_second: String(second.tick),
	};
}


function leftoverDaxnutsTickN(state, n) {
	for (let i = 0; i < n; i += 1) {
		leftoverDaxnutsTick(state);
	}
	return state;
}


function runCliSelectorsDaxnutsComponentTick() {
	const ui = leftoverDaxnutsBenchUi();
	const one = leftoverMakeDaxnutsComponentState(ui);
	const maxed = leftoverMakeDaxnutsComponentState(ui);
	const after = leftoverMakeDaxnutsComponentState(ui);
	leftoverDaxnutsTick(one);
	leftoverDaxnutsTickN(maxed, 25);
	leftoverDaxnutsTickN(after, 25);
	leftoverDaxnutsTick(after);
	return {
		dct_one: String(one.tick),
		dct_max: String(maxed.tick),
		dct_stop: maxed.stopped ? "1" : "0",
		dct_after: String(after.tick),
		dct_renders: String(ui.renders),
	};
}


function countdownSeconds(timeoutMs) {
	return String(Math.ceil(timeoutMs / 1000));
}


function runCliSelectorsCountdownSeconds() {
	return {
		cds_0: countdownSeconds(0),
		cds_1: countdownSeconds(1),
		cds_1000: countdownSeconds(1000),
		cds_1001: countdownSeconds(1001),
		cds_1500: countdownSeconds(1500),
		cds_999: countdownSeconds(999),
	};
}


function runCliSelectorsCountdownTick() {
	let ticks = 0;
	let expires = 0;
	let renders = 0;
	let remainingSeconds = Math.ceil(3000 / 1000);
	ticks += 1;
	const afterMake = ticks;
	const tick = () => {
		remainingSeconds -= 1;
		ticks += 1;
		renders += 1;
		if (remainingSeconds <= 0) {
			expires += 1;
		}
	};
	tick();
	tick();
	tick();
	return {
		cdt_make: String(afterMake),
		cdt_remain: String(remainingSeconds),
		cdt_expired: remainingSeconds <= 0 ? "1" : "0",
		cdt_ticks: String(ticks),
		cdt_expires: String(expires),
		cdt_renders: String(renders),
	};
}


function countdownRenderCount(kind, calls) {
	let n = 0;
	const tui =
		kind === "fn"
			? {
					requestRender() {
						n += 1;
					},
				}
			: undefined;
	for (let index = 0; index < calls; index += 1) {
		tui?.requestRender();
	}
	return String(n);
}


function runCliSelectorsCountdownRender() {
	return {
		cdr_fn1: countdownRenderCount("fn", 1),
		cdr_fn2: countdownRenderCount("fn", 2),
		cdr_nil: countdownRenderCount("nil", 1),
		cdr_sym: countdownRenderCount("sym", 1),
		cdr_zero: countdownRenderCount("fn", 0),
		cdr_fn3: countdownRenderCount("fn", 3),
	};
}


