function encodeModelSelectorSearchTextTable(allModels, scopedModels) {
	const table = new Map();
	const texts = [];
	for (const item of allModels) {
		const text = modelSelectorSearchText(item);
		table.set(item, text);
		texts.push(text);
	}
	for (const item of scopedModels) {
		if (!table.has(item)) {
			const text = modelSelectorSearchText(item);
			table.set(item, text);
			texts.push(text);
		}
	}
	return `${table.size}|${texts.join(";")}`;
}


