function scopedModelsSelectorNotifyChangeEncoded(
	enabledIds,
	withCallback,
	times = 1,
) {
	let payload = "";
	let n = 0;
	const onChange = withCallback
		? (ids) => {
				n += 1;
				payload = ids === null ? "all" : ids.join(",");
			}
		: undefined;
	for (let i = 0; i < times; i++) {
		if (onChange) {
			onChange(enabledIds === null ? null : [...enabledIds]);
		}
	}
	return `${payload}|${n}`;
}


