function lispMod(n, m) {
	if (m <= 0) {
		return 0;
	}
	return ((n % m) + m) % m;
}

const GOAL20_USER_MESSAGE_DEFAULT_KB = new keybindingsModule.KeybindingsManager(
	keybindingsModule.TUI_KEYBINDINGS,
);


function goal20UserMessageItems(...values) {
	return values.map((value) => ({ label: value, value }));
}


function makeUserMessageSelectorState({ items = [], initialSelectedValue, maxVisible = 10, keybindings = "bench" } = {}) {
	let initial = null;
	if (initialSelectedValue != null) {
		const idx = items.findIndex((item) => item.value === initialSelectedValue);
		if (idx >= 0) {
			initial = idx;
		}
	}
	const selected = initial !== null ? initial : Math.max(0, items.length - 1);
	return {
		items: items.slice(),
		selected,
		maxVisible: Math.max(1, maxVisible),
	};
}


function userMessageSelectorMove(state, delta) {
	const count = state.items.length;
	state.selected = lispMod(state.selected + delta, count > 0 ? count : 0);
	if (count <= 0) {
		state.selected = 0;
	}
	return state;
}


function userMessageSelectorSelectionText(state) {
	const item = state.items[state.selected];
	return item ? item.value : "";
}


function runCliSelectorsUserMessageMake() {
	const one = goal20UserMessageItems("a");
	const two = goal20UserMessageItems("a", "b");
	const three = goal20UserMessageItems("a", "b", "c");
	const emptyState = makeUserMessageSelectorState({ items: [] });
	const oneState = makeUserMessageSelectorState({ items: one });
	const twoState = makeUserMessageSelectorState({ items: two });
	const hitState = makeUserMessageSelectorState({
		items: three,
		initialSelectedValue: "a",
	});
	const missState = makeUserMessageSelectorState({
		items: two,
		initialSelectedValue: "z",
	});
	const orig = goal20UserMessageItems("a");
	const copyState = makeUserMessageSelectorState({ items: orig });
	orig.push(...goal20UserMessageItems("x"));
	return {
		umm_empty: emptyState.selected,
		umm_one: oneState.selected,
		umm_two: twoState.selected,
		umm_hit: hitState.selected,
		umm_miss: missState.selected,
		umm_copy: copyState.items.length,
	};
}


function runCliSelectorsUserMessageMove() {
	const empty = makeUserMessageSelectorState({ items: [] });
	const twoFwd = makeUserMessageSelectorState({
		items: goal20UserMessageItems("a", "b"),
	});
	const twoBack = makeUserMessageSelectorState({
		items: goal20UserMessageItems("a", "b"),
	});
	const twoFull = makeUserMessageSelectorState({
		items: goal20UserMessageItems("a", "b"),
	});
	const threeBack = makeUserMessageSelectorState({
		items: goal20UserMessageItems("a", "b", "c"),
	});
	const threeFwd = makeUserMessageSelectorState({
		items: goal20UserMessageItems("a", "b", "c"),
	});
	userMessageSelectorMove(empty, 1);
	userMessageSelectorMove(twoFwd, 1);
	userMessageSelectorMove(twoBack, -1);
	userMessageSelectorMove(twoFull, 2);
	userMessageSelectorMove(threeBack, -1);
	userMessageSelectorMove(threeFwd, 1);
	return {
		umv_empty: empty.selected,
		umv_wrap_fwd: twoFwd.selected,
		umv_back: twoBack.selected,
		umv_full: twoFull.selected,
		umv_three_back: threeBack.selected,
		umv_three_fwd: threeFwd.selected,
	};
}


function runCliSelectorsUserMessageSelection() {
	const empty = makeUserMessageSelectorState({ items: [] });
	const two = makeUserMessageSelectorState({
		items: goal20UserMessageItems("a", "b"),
	});
	const hit = makeUserMessageSelectorState({
		items: goal20UserMessageItems("a", "b", "c"),
		initialSelectedValue: "a",
	});
	const moved = makeUserMessageSelectorState({
		items: goal20UserMessageItems("a", "b"),
	});
	const miss = makeUserMessageSelectorState({
		items: goal20UserMessageItems("a", "b"),
		initialSelectedValue: "z",
	});
	const one = makeUserMessageSelectorState({
		items: goal20UserMessageItems("only"),
	});
	userMessageSelectorMove(moved, 1);
	return {
		ums_empty: userMessageSelectorSelectionText(empty),
		ums_last: userMessageSelectorSelectionText(two),
		ums_hit: userMessageSelectorSelectionText(hit),
		ums_wrap: userMessageSelectorSelectionText(moved),
		ums_miss: userMessageSelectorSelectionText(miss),
		ums_one: userMessageSelectorSelectionText(one),
	};
}


function userMessageActionName(action) {
	return action ? String(action) : "null";
}


function userMessageSelectorHandleEvent(state, eventKind) {
	switch (eventKind) {
		case "up":
			userMessageSelectorMove(state, -1);
			return { action: "changed", value: null };
		case "down":
			userMessageSelectorMove(state, 1);
			return { action: "changed", value: null };
		case "enter":
		case "submit": {
			const value = userMessageSelectorSelectionText(state);
			if (value) {
				return { action: "select", value };
			}
			return { action: null, value: null };
		}
		case "escape":
		case "cancel":
		case "interrupt":
			return { action: "cancel", value: null };
		default:
			return { action: null, value: null };
	}
}


function encodeUserMessageHandleEvent(state, result) {
	return [
		userMessageActionName(result.action),
		result.value == null || result.value === "" ? "null" : result.value,
		String(state.selected),
	].join("|");
}


function userMessageHandleEventEncoded(items, eventKind, extra = {}) {
	const state = makeUserMessageSelectorState({ items, ...extra });
	const result = userMessageSelectorHandleEvent(state, eventKind);
	return encodeUserMessageHandleEvent(state, result);
}


function runCliSelectorsUserMessageHandleEvent() {
	return {
		umhe_down: userMessageHandleEventEncoded(goal20UserMessageItems("a", "b", "c"), "down"),
		umhe_enter: userMessageHandleEventEncoded(goal20UserMessageItems("a", "b"), "enter"),
		umhe_esc: userMessageHandleEventEncoded(goal20UserMessageItems("a", "b"), "escape"),
		umhe_text: userMessageHandleEventEncoded(goal20UserMessageItems("a", "b"), "text"),
		umhe_empty: userMessageHandleEventEncoded([], "enter"),
	};
}


function userMessageSelectorHandleRawInput(state, data) {
	const manager = GOAL20_USER_MESSAGE_DEFAULT_KB;
	if (selectorKeybindingMatchesPi(manager, data, "tui.select.up")) {
		userMessageSelectorMove(state, -1);
		return { action: "changed", value: null, consumed: true };
	}
	if (selectorKeybindingMatchesPi(manager, data, "tui.select.down")) {
		userMessageSelectorMove(state, 1);
		return { action: "changed", value: null, consumed: true };
	}
	if (selectorKeybindingMatchesPi(manager, data, "tui.select.confirm")) {
		const value = userMessageSelectorSelectionText(state);
		return { action: value ? "select" : null, value: value || null, consumed: true };
	}
	if (selectorKeybindingMatchesPi(manager, data, "tui.select.cancel")) {
		return { action: "cancel", value: null, consumed: true };
	}
	return { action: null, value: null, consumed: false };
}


function encodeUserMessageHandleRaw(state, result) {
	return [
		userMessageActionName(result.action),
		result.value == null || result.value === "" ? "null" : result.value,
		String(state.selected),
		result.consumed ? "true" : "false",
	].join("|");
}


function userMessageHandleRawEncoded(items, data, extra = {}) {
	const state = makeUserMessageSelectorState({ items, ...extra });
	const result = userMessageSelectorHandleRawInput(state, data);
	return encodeUserMessageHandleRaw(state, result);
}


function runCliSelectorsUserMessageHandleRaw() {
	const arrowDown = "\x1b[B";
	const arrowUp = "\x1b[A";
	const enter = "\r";
	const escape = "\x1b";
	return {
		umhr_down: userMessageHandleRawEncoded(goal20UserMessageItems("a", "b", "c"), arrowDown),
		umhr_up: userMessageHandleRawEncoded(goal20UserMessageItems("a", "b", "c"), arrowUp),
		umhr_enter: userMessageHandleRawEncoded(goal20UserMessageItems("a", "b"), enter),
		umhr_esc: userMessageHandleRawEncoded(goal20UserMessageItems("a", "b"), escape),
		umhr_nop: userMessageHandleRawEncoded(goal20UserMessageItems("a", "b"), "q"),
	};
}


function renderUserMessageSelector(state, width) {
	const items = state.items;
	if (items.length === 0) {
		return [`  No user messages found|${width}`];
	}
	return items.map((item, index) => {
		const selectedP = index === state.selected;
		const text = String(item.label ?? item.value ?? "")
			.replace(/\n/g, " ")
			.trim();
		const message = text.slice(0, Math.max(0, width - 2));
		return `${selectedP ? "› " : "  "}${message}|  Message ${index + 1} of ${items.length}`;
	});
}


function encodeRenderUserMessageSelector(items, width, extra = {}) {
	const state = makeUserMessageSelectorState({ items, ...extra });
	renderUserMessageSelector(state, width);
	return `${state.selected}|${state.items.length}|${width}|${userMessageSelectorSelectionText(state)}`;
}


function runCliSelectorsRenderUserMessageSelector() {
	return {
		umrd_three: encodeRenderUserMessageSelector(goal20UserMessageItems("a", "b", "c"), 80),
		umrd_one: encodeRenderUserMessageSelector(goal20UserMessageItems("only"), 80),
		umrd_empty: encodeRenderUserMessageSelector([], 80),
		umrd_narrow: encodeRenderUserMessageSelector(goal20UserMessageItems("a", "b", "c"), 40),
		umrd_hit: encodeRenderUserMessageSelector(goal20UserMessageItems("a", "b", "c"), 80, {
			initialSelectedValue: "a",
		}),
	};
}


function loginDialogSectionsEncoded(state) {
	return state.sections
		.map((section) => {
			switch (section.kind) {
				case "url":
					return `url:${section.url}`;
				case "warning":
					return `warn:${section.text}`;
				case "dim":
					return `dim:${section.text}`;
				case "text":
					return `text:${section.text}`;
				case "link":
					return `link:${section.text}@${section.url}`;
				case "muted":
					return `muted:${section.text}`;
				case "accent":
					return `accent:${section.text}`;
				case "submitted":
					return `sub:${section.text}`;
				default:
					return section.kind;
			}
		})
		.join("|");
}


function makeLoginDialogState(providerName) {
	return {
		providerName,
		sections: [],
		input: null,
		cancelFunction: null,
	};
}


function loginDialogShowAuth(state, url, instructions) {
	const sections = [{ kind: "blank" }, { kind: "url", url }];
	if (instructions && instructions.length > 0) {
		sections.push({ kind: "blank" }, { kind: "warning", text: instructions });
	}
	state.sections = sections;
	return state;
}


function loginDialogShowDeviceCode(state, url, userCode) {
	state.sections = [
		{ kind: "blank" },
		{ kind: "url", url },
		{ kind: "blank" },
		{ kind: "warning", text: `Enter code: ${userCode}` },
	];
	return state;
}


