const GOAL20_THINKING_DEFAULT_KB = new keybindingsModule.KeybindingsManager(
	GOAL20_THINKING_DEFINITIONS,
);
const GOAL20_THINKING_CUSTOM_KB = new keybindingsModule.KeybindingsManager(
	GOAL20_THINKING_DEFINITIONS,
	{ "app.thinking.save": "ctrl+k" },
);


