function removeRuntimeOnlyOptions(options) {
	const drop = new Set(["apiKey", "headers", "environment", "authType"]);
	const rest = {};
	for (const [key, value] of Object.entries(options)) {
		if (!drop.has(key)) {
			rest[key] = value;
		}
	}
	return rest;
}

function runProviderStripRuntimeOptions() {
	const mixed = removeRuntimeOnlyOptions({
		apiKey: "sk",
		headers: { h: "v" },
		environment: { k: "v" },
		authType: "oauth",
		maxTokens: 16,
		temperature: 0.2,
	});
	const onlyRuntime = removeRuntimeOnlyOptions({
		apiKey: "sk",
		headers: null,
		environment: null,
		authType: "oauth",
	});
	return {
		sro_keep: mixed.maxTokens === 16 ? 1 : 0,
		sro_drop: mixed.apiKey === undefined ? 1 : 0,
		sro_n: Object.keys(mixed).length,
		sro_empty: Object.keys(onlyRuntime).length === 0 ? 1 : 0,
		sro_temp: mixed.temperature === 0.2 ? 1 : 0,
	};
}

function leftoverOauthLoginPresent(provider) {
	return typeof provider?.auth?.oauth?.login === "function" ? 1 : 0;
}

function leftoverOauthRefreshPresent(provider) {
	return typeof provider?.auth?.oauth?.refresh === "function" ? 1 : 0;
}

function leftoverOauthToAuth(providerId, access) {
	if (providerId === "anthropic") {
		return { apiKey: access };
	}
	if (providerId === "kimi-coding") {
		return { headers: { Authorization: `Bearer ${access}` } };
	}
	return null;
}

