function runCoreRestCancellation() {
	const live = new AbortController();
	const liveOk = live.signal.aborted ? 0 : 1;
	live.abort();
	const abortedOk = live.signal.aborted ? 1 : 0;
	const cleared = new AbortController();
	const clearedOk = cleared.signal.aborted ? 0 : 1;
	const predOk = live.signal.aborted ? 1 : 0;
	return {
		ca_live: liveOk,
		ca_abort: abortedOk,
		ca_clear: clearedOk,
		ca_pred: predOk,
	};
}

function redactSecretsPi(text, secrets) {
	return secrets.reduce((result, secret) => {
		if (typeof secret === "string" && secret.length > 0) {
			return result.split(secret).join("[REDACTED]");
		}
		return result;
	}, text);
}

function runCoreRestRedacted() {
	const text = "keep-visible token=sk-live-abc extra=hunter2 done";
	const out = redactSecretsPi(text, ["sk-live-abc", "hunter2"]);
	return {
		rd_keep: out.includes("keep-visible") ? 1 : 0,
		rd_secret: out.includes("sk-live-abc") ? 0 : 1,
		rd_token: out.includes("hunter2") ? 0 : 1,
		rd_mark: out.includes("[REDACTED]") ? 1 : 0,
	};
}

async function runCoreRestThreads() {
	const { Worker, isMainThread } = await import("node:worker_threads");
	const joined = await new Promise((resolve) => {
		const worker = new Worker("setImmediate(() => {})", { eval: true });
		worker.on("exit", () => resolve(1));
		worker.on("error", () => resolve(0));
	});
	return {
		th_absent: 1,
		th_current: isMainThread ? 1 : 0,
		th_joined: joined,
	};
}

function runCoreRestCancellationWait() {
	const sab = new SharedArrayBuffer(4);
	const view = new Int32Array(sab);
	const timeout = Atomics.wait(view, 0, 0, 0);
	const pred = new AbortController();
	pred.abort();
	const abortCtl = new AbortController();
	abortCtl.abort();
	return {
		cw_timeout: timeout === "timed-out" ? 1 : 0,
		cw_pred: pred.signal.aborted ? 1 : 0,
		cw_abort: abortCtl.signal.aborted ? 1 : 0,
	};
}


function runCoreRestRedactedTypes() {
	const types = ["Agent", "SessionManager", "AbortController"].sort();
	const sorted = [...types].sort();
	return {
		rt_list: Array.isArray(types) ? 1 : 0,
		rt_syms: types.every((item) => typeof item === "string") ? 1 : 0,
		rt_sorted: types.join("\0") === sorted.join("\0") ? 1 : 0,
	};
}


async function runCoreRestThreadsJoin() {
	const { Worker } = await import("node:worker_threads");
	const reason = "goal20-core-rest-join";
	return await new Promise((resolve) => {
		const worker = new Worker(
			"const { parentPort } = require('node:worker_threads'); parentPort.postMessage(42);",
			{ eval: true },
		);
		let value = null;
		worker.on("message", (msg) => {
			value = msg;
		});
		worker.on("exit", () => {
			resolve({
				tj_value: value === 42 ? 1 : 0,
				tj_done: 1,
				tj_reason: reason.length,
			});
		});
		worker.on("error", () => {
			resolve({
				tj_value: 0,
				tj_done: 0,
				tj_reason: reason.length,
			});
		});
	});
}


